WITH parsed AS (SELECT id, service, host, log_ts, level, latency_ms, payload_json, context, GET_JSON_OBJECT(payload_json, '$.user.tier') AS user_tier, FROM_JSON(payload_json, 'STRUCT<user: STRUCT<id: INT, tier: STRING>, duration: DOUBLE, retries: INT, tags: ARRAY<STRING>>').retries AS retry_count, context['region'] AS region, context['version'] AS version, SHIFTRIGHT(status_code, 2) AS status_code_high FROM app_logs WHERE service IN ('checkout', 'auth', 'search')) SELECT id, service, host, log_ts, level, latency_ms, payload_json, context, user_tier, retry_count, region, version, status_code_high, NTILE(5) OVER (PARTITION BY service ORDER BY status_code_high, id) AS status_code_high_bucket, LAST_VALUE(version) IGNORE NULLS OVER w_ordered AS last_known_version, SUM(latency_ms) OVER (ORDER BY log_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_latency_ms, DENSE_RANK() OVER w_running AS retry_count_dense_rank, AVG(retry_count) OVER (ORDER BY CAST(log_ts AS BIGINT) RANGE BETWEEN 900 PRECEDING AND CURRENT ROW) AS retry_count_avg_15m FROM parsed WINDOW w_ordered AS (PARTITION BY service ORDER BY status_code_high, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), w_running AS (ORDER BY retry_count NULLS FIRST);
